import java.util.Scanner;

public class Main {
    static final int MAXK = 31;
    static final long MOD = 1000000007L;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = readLong(sc);
        long base = readLong(sc);
        int len = 0;
        long[] digits = new long[70];

        while (n > 0) {
            digits[len++] = n % base;
            n /= base;
        }

        long[][][] A = new long[70][MAXK][MAXK];
        long[][] pre = new long[MAXK][MAXK];
        long[][] suf = new long[MAXK][MAXK];
        long[][] ans = new long[MAXK][MAXK];
        long[][] I = new long[MAXK][MAXK];

        initI(I, (int) base);
        prepare(A, pre, suf, I, digits, len, (int) base);

        long[][] answer = new long[MAXK][MAXK];
        for (int i = 0; i < MAXK; i++) {
            for (int j = 0; j < MAXK; j++) {
                answer[i][j] = 0;
            }
        }
        for (int i = 0; i <= base; i++) {
            answer[i][0] = (i == 0) ? 1 : 0;
        }

        long x = 0;
        for (int i = len - 1; i >= 0; i--) {
            for (long j = 0; j < digits[i]; j++) {
                matMul(A, (int) i, (int) base, (j + x) % base, answer, answer);
            }
            x = (x + digits[i]) % base;
        }

        long res = 0;
        for (int i = 0; i < base; i++) {
            res = (res + answer[i][0]) % MOD;
        }
        System.out.println(res + 1);
        sc.close();
    }

    static long readLong(Scanner sc) {
        return sc.nextLong();
    }

    static void initI(long[][] I, int base) {
        for (int i = 0; i <= base; i++) {
            for (int j = 0; j <= base; j++) {
                I[i][j] = 0;
            }
        }
        for (int i = 0; i <= base; i++) {
            I[i][i] = 1;
        }
    }

    static void prepare(long[][][] A, long[][] pre, long[][] suf, long[][] I, long[] digits, int len, int base) {
        for (int i = 0; i < base; i++) {
            for (int j = 0; j <= base; j++) {
                A[0][i][j] = 0;
            }
            A[0][i][i] = 1;
            A[0][i][0] = 1;
        }
        for (int i = 1; i < len; i++) {
            copyMatrix(A[i - 1][0], pre);
            for (int j = 1; j < base; j++) {
                matMul(A, i - 1, base, j, pre, pre);
            }
            copyMatrix(A[i - 1][base - 1], suf);
            for (int j = base - 2; j >= 0; j--) {
                matMul(suf, A, i - 1, base, j, suf);
            }
            for (int j = 0; j < base; j++) {
                if (j > 0) {
                    matMul(pre, j - 1, suf, j, A, i);
                } else {
                    matMul(I, suf, j, A, i);
                }
            }
        }
    }

    static void copyMatrix(long[] src, long[][] dest) {
        for (int i = 0; i < src.length; i++) {
            dest[0][i] = src[i];
        }
    }

    static void matMul(long[][][] A, int i, int base, int j, long[][] src, long[][] dest) {
        long[][] C = new long[MAXK][MAXK];
        for (int x = 0; x <= base; x++) {
            for (int y = 0; y <= base; y++) {
                C[x][y] = 0;
            }
        }
        for (int k = 0; k <= base; k++) {
            for (int y = 0; y <= base; y++) {
                for (int x = 0; x <= base; x++) {
                    C[x][y] = (C[x][y] + A[i][x][k] * src[k][y]) % MOD;
                }
            }
        }
        for (int x = 0; x <= base; x++) {
            for (int y = 0; y <= base; y++) {
                dest[x][y] = C[x][y];
            }
        }
    }

    static void matMul(long[][][] A, int i, int base, int j, long[][] src, long[][] dest) {
        long[][] C = new long[MAXK][MAXK];
        for (int x = 0; x <= base; x++) {
            for (int y = 0; y <= base; y++) {
                C[x][y] = 0;
            }
        }
        for (int k = 0; k <= base; k++) {
            for (int y = 0; y <= base; y++) {
                for (int x = 0; x <= base; x++) {
                    C[x][y] = (C[x][y] + A[i][x][k] * src[k][y]) % MOD;
                }
            }
        }
        for (int x = 0; x <= base; x++) {
            for (int y = 0; y <= base; y++) {
                dest[x][y] = C[x][y];
            }
        }
    }

    static void matMul(long[][] src, int row, long[][] dest, int col, long[][] result) {
        long sum = 0;
        for (int k = 0; k < src[0].length; k++) {
            sum = (sum + src[row][k] * dest[k][col]) % MOD;
        }
        result[row][col] = sum;
    }
